const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cairns = ee.Geometry.Point([145.7781, -16.9186]);
  const cooktown = ee.Geometry.Point([145.248920, -15.475923]);
  const startDate = '2025-01-31';
  const endDate = '2025-02-05'; // Exclusive end date

  // 2. Data Acquisition - CHIRPS Daily Precipitation
  const precip = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate);

  const imageCount = precip.size().getInfo();
  console.log(`Total images in collection: ${imageCount}`);

  if (imageCount === 0) {
    console.log("No precipitation data available for this period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate total rainfall for both locations
  const totalPrecip = precip.sum();

  // Calculate for Cairns
  const cairnsStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: cairns,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  // Calculate for Cooktown
  const cooktownStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.sum().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: cooktown,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const cairnsRainfall = cairnsStats.precipitation_sum;
  const cairnsCount = cairnsStats.precipitation_count;
  const cooktownRainfall = cooktownStats.precipitation_sum;
  const cooktownCount = cooktownStats.precipitation_count;

  console.log(`Cairns: ${cairnsRainfall !== null ? cairnsRainfall.toFixed(2) : 'null'} mm, Pixels: ${cairnsCount}`);
  console.log(`Cooktown: ${cooktownRainfall !== null ? cooktownRainfall.toFixed(2) : 'null'} mm, Pixels: ${cooktownCount}`);

  // 4. Validation & Final Answer
  if (cairnsCount === 0 || cooktownCount === 0) {
    console.log("No valid pixels found for one or both locations.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (cairnsRainfall === null || cooktownRainfall === null || 
      isNaN(cairnsRainfall) || isNaN(cooktownRainfall) ||
      cairnsRainfall < 0 || cooktownRainfall < 0 ||
      cairnsRainfall > 2000 || cooktownRainfall > 2000) {
    console.log("Invalid rainfall values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Compare rainfall amounts
  if (cairnsRainfall > cooktownRainfall) {
    console.log("Cairns received more rainfall than Cooktown.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Cairns did not receive more rainfall than Cooktown.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
